statsFn:
const drawWindow=(drawCount,field)=>{
  const rows=all.slice(-drawCount);
  return {...aggregate(rows,field),requested_draws:drawCount,available_draws:rows.length,
    missing_draws:Math.max(0,drawCount-rows.length),complete:rows.length===drawCount,
    basis:'verified_walk_forward_draws',missing_data_note:rows.length<drawCount?
    'Chưa đủ kỳ hồi kiểm xác thực; không tự điền dữ liệu':null};
};

uiRenderer:
function renderBacktestSummary(p,b){
 if(!b){$('statsBacktest').innerHTML='<div class="stats60-foot">Chưa có dữ liệu hồi kiểm.</div>';return}
 const f=n=>Number(n||0).toLocaleString('vi-VN');
 const row=n=>{
  const full=b['stats'+n],red=b['reduced_stats'+n];
  if(!full||!red)return '<div class="stats60-foot">'+f(n)+' kỳ: chưa có dữ liệu xác thực.</div>';
  const count=Number(red.available_draws??red.draws_tested??0),jp=jackpotTickets(p,red.prize_counts||{}),g1=pcount(red.prize_counts||{},'Giải nhất');
  const st=red.complete===true?'Đủ dữ liệu':'CHƯA ĐỦ '+f(Math.max(0,n-count))+' kỳ';
  const split=p==='power655'?' (JP1 '+f(pcount(red.prize_counts||{},'Jackpot 1'))+' / JP2 '+f(pcount(red.prize_counts||{},'Jackpot 2'))+')':'';
  return '<div class="stat60-row em"><span>'+f(n)+' kỳ</span><b>'+f(count)+'/'+f(n)+' — '+st+'</b></div>'+
   '<div class="stat60-row jp"><span>JP dàn cuối'+split+'</span><b>'+f(jp)+'</b></div>'+
   '<div class="stat60-row first"><span>G1 dàn cuối</span><b>'+f(g1)+'</b></div>'+
   '<div class="stats60-foot">Dàn sau lọc cứng: '+f(jackpotTickets(p,full.prize_counts||{}))+' JP, '+f(pcount(full.prize_counts||{},'Giải nhất'))+' G1. Trung bình dàn cuối '+f(red.avg_pool)+' bộ/kỳ. '+fmt(red.window_start)+' → '+fmt(red.window_end)+'</div>';
 };
 $('statsBacktest').innerHTML=[30,60,150,1500].map(row).join('')+
  '<div class="stats60-foot">Mốc 30 kỳ: mục tiêu 5 JP và 2.000 G1 kết hợp hai sản phẩm; không bảo đảm đạt.</div>';
}

apiRoute:
if(req.method==='GET'&&url.pathname==='/api/draw-window-stats'){
  try{
    const data=JSON.parse(await readFile(resolve(ROOT,'public/backtest-60.json'),'utf8'));
    const products={};
    for(const product of ['mega645','power655']){
      const stats=data.products?.[product]||{};
      products[product]={};
      for(const n of [30,60,150,1500]){
        const full=stats['stats'+n]||null,red=stats['reduced_stats'+n]||null;
        const c=red?.prize_counts||{},q=full?.prize_counts||{};
        products[product][String(n)]={requested:n,available:red?.available_draws||0,complete:red?.complete===true,
          from:red?.window_start||null,to:red?.window_end||null,
          jackpot:(c.Jackpot||0)+(c['Jackpot 1']||0)+(c['Jackpot 2']||0),
          jackpot1:c['Jackpot 1']||0,jackpot2:c['Jackpot 2']||0,g1:c['Giải nhất']||0,
          full_jackpot:(q.Jackpot||0)+(q['Jackpot 1']||0)+(q['Jackpot 2']||0),full_g1:q['Giải nhất']||0,
          average_pool:red?.avg_pool||0};
      }
    }
    return send(res,200,{ok:true,source:'verified_walk_forward_24_shards',generated_at:data.generated_at,products,
      goal30:{jackpot:5,first_prizes:2000},note:'Mục tiêu không bảo đảm, kỳ thiếu được báo rõ'});
  }catch(e){return send(res,503,{ok:false,error:'draw_stats_unavailable'})}
}

